package com.rulecraft.decisionops.simulation;

import com.rulecraft.decisionops.audit.AuditService;import com.rulecraft.decisionops.catalog.CatalogService;import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;import com.rulecraft.decisionops.platform.web.DomainProblemException;import com.rulecraft.decisionops.projects.ProjectAccessPolicy;import com.rulecraft.decisionops.simulation.domain.*;import com.rulecraft.decisionops.simulation.persistence.*;import com.rulecraft.decisionops.tests.DecisionTestService;import com.rulecraft.decisionops.tests.domain.DecisionTestCase;import com.rulecraft.decisionops.tests.persistence.DecisionTestCaseRepository;
import java.time.*;import java.util.*;import org.springframework.boot.context.event.ApplicationReadyEvent;import org.springframework.context.event.EventListener;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tools.jackson.core.JacksonException;import tools.jackson.core.type.TypeReference;import tools.jackson.databind.*;

@Service
public class RegressionMatrixService {
    private final RegressionMatrixRunRepository runs;private final RegressionMatrixResultRepository results;private final DecisionTestCaseRepository tests;private final DecisionTestService decisionTests;private final ProjectAccessPolicy access;private final CatalogService catalog;private final AuditService audit;private final ObjectMapper mapper;private final Clock clock;
    public RegressionMatrixService(RegressionMatrixRunRepository runs,RegressionMatrixResultRepository results,DecisionTestCaseRepository tests,DecisionTestService decisionTests,ProjectAccessPolicy access,CatalogService catalog,AuditService audit,ObjectMapper mapper,Clock clock){this.runs=runs;this.results=results;this.tests=tests;this.decisionTests=decisionTests;this.access=access;this.catalog=catalog;this.audit=audit;this.mapper=mapper;this.clock=clock;}
    @EventListener(ApplicationReadyEvent.class)public void recoverInterrupted(){runs.interruptRunning(Instant.now(clock));}
    @Transactional(readOnly=true)public List<MatrixRunSummary> list(RuleCraftPrincipal actor,UUID projectId,UUID serviceId){context(actor,projectId,serviceId);return runs.findTop20ByDecisionServiceIdAndTenantIdAndProjectIdOrderByStartedAtDesc(serviceId,actor.tenantId(),projectId).stream().map(this::summary).toList();}
    @Transactional(readOnly=true)public MatrixRunView get(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID runId){context(actor,projectId,serviceId);return view(require(actor,projectId,serviceId,runId));}
    public MatrixRunView execute(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,MatrixRunCommand command){context(actor,projectId,serviceId);var selection=normalize(command);var serialized=json(selection);var existing=runs.findByTenantIdAndDecisionServiceIdAndClientRequestId(actor.tenantId(),serviceId,command.clientRequestId());if(existing.isPresent()){if(!existing.get().getSelectionJson().equals(serialized))conflict("RC-MATRIX-REQUEST-CONFLICT","This request ID was already used for a different scenario selection.");return view(existing.get());}
        var selected=new ArrayList<DecisionTestCase>();for(var testId:selection)selected.add(tests.findByIdAndDecisionServiceIdAndTenantIdAndProjectId(testId,serviceId,actor.tenantId(),projectId).orElseThrow(()->notFound()));var now=Instant.now(clock);RegressionMatrixRun run;try{run=runs.saveAndFlush(new RegressionMatrixRun(actor.tenantId(),projectId,serviceId,command.clientRequestId(),serialized,selection.size(),actor.userId(),now));}catch(DataIntegrityViolationException race){var duplicate=runs.findByTenantIdAndDecisionServiceIdAndClientRequestId(actor.tenantId(),serviceId,command.clientRequestId()).orElseThrow(()->race);if(!duplicate.getSelectionJson().equals(serialized))conflict("RC-MATRIX-REQUEST-CONFLICT","This request ID was already used for a different scenario selection.");return view(duplicate);}
        audit.record(actor.tenantId(),actor.userId(),"REGRESSION_MATRIX_STARTED","REGRESSION_MATRIX",run.getId(),Map.of("serviceId",serviceId,"selectedCount",selection.size()));int passed=0,failed=0,errors=0;for(int index=0;index<selected.size();index++){var test=selected.get(index);try{var result=decisionTests.run(actor,projectId,serviceId,test.getId());results.saveAndFlush(RegressionMatrixResult.completed(run.getId(),index,test,result,json(result.expectedOutputs()),json(result.actualOutputs()),json(result.decisions()),Instant.now(clock)));if(result.status().name().equals("PASSED"))passed++;else failed++;}catch(DomainProblemException problem){results.saveAndFlush(RegressionMatrixResult.error(run.getId(),index,test,test.getExpectedOutputsJson(),problem.getCode(),safe(problem.getMessage()),Instant.now(clock)));errors++;}catch(RuntimeException problem){results.saveAndFlush(RegressionMatrixResult.error(run.getId(),index,test,test.getExpectedOutputsJson(),"RC-MATRIX-CASE-ERROR","The scenario could not be evaluated. Retry the matrix or inspect the service configuration.",Instant.now(clock)));errors++;}}
        run.complete(passed,failed,errors,Instant.now(clock));runs.saveAndFlush(run);audit.record(actor.tenantId(),actor.userId(),"REGRESSION_MATRIX_COMPLETED","REGRESSION_MATRIX",run.getId(),Map.of("serviceId",serviceId,"passed",passed,"failed",failed,"errors",errors));return view(run);
    }
    private List<UUID> normalize(MatrixRunCommand command){if(command==null||command.clientRequestId()==null)bad("RC-MATRIX-REQUEST-ID","Provide a client request ID so retries remain idempotent.");if(command.testCaseIds()==null||command.testCaseIds().isEmpty())bad("RC-MATRIX-SELECTION","Select at least one scenario.");if(command.testCaseIds().size()>100)bad("RC-MATRIX-LIMIT","A regression matrix can execute at most 100 scenarios.");var unique=new LinkedHashSet<>(command.testCaseIds());if(unique.contains(null)||unique.size()!=command.testCaseIds().size())bad("RC-MATRIX-SELECTION","Select each scenario exactly once.");return List.copyOf(unique);}
    private void context(RuleCraftPrincipal actor,UUID projectId,UUID serviceId){access.requireVisible(actor,projectId);catalog.getService(actor,projectId,serviceId);}
    private RegressionMatrixRun require(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID runId){return runs.findByIdAndDecisionServiceIdAndTenantIdAndProjectId(runId,serviceId,actor.tenantId(),projectId).orElseThrow(this::notFound);}
    private DomainProblemException notFound(){return new DomainProblemException(HttpStatus.NOT_FOUND,"RC-MATRIX-NOT-FOUND","Regression matrix not found.");}
    private MatrixRunSummary summary(RegressionMatrixRun run){return new MatrixRunSummary(run.getId(),run.getClientRequestId(),run.getStatus(),run.getSelectedCount(),run.getPassedCount(),run.getFailedCount(),run.getErrorCount(),run.getStartedAt(),run.getCompletedAt());}
    private MatrixRunView view(RegressionMatrixRun run){return new MatrixRunView(summary(run),parseIds(run.getSelectionJson()),results.findAllByMatrixRunIdOrderByPositionAsc(run.getId()).stream().map(this::resultView).toList());}
    private MatrixCaseView resultView(RegressionMatrixResult value){return new MatrixCaseView(value.getId(),value.getPosition(),value.getTestCaseId(),value.getTestCaseVersion(),value.getTestKey(),value.getTestName(),value.getStatus(),value.getTestRunId(),value.getEvaluationId(),value.getGraphVersion(),parseMap(value.getExpectedOutputsJson()),parseNullableMap(value.getActualOutputsJson()),parseDecisions(value.getDecisionResultsJson()),value.getErrorCode(),value.getErrorDetail(),value.getExecutedAt());}
    private String safe(String message){return message==null?"The scenario could not be evaluated.":message.substring(0,Math.min(500,message.length()));}private String json(Object value){try{return mapper.writeValueAsString(value);}catch(JacksonException failure){throw new IllegalStateException("Matrix data could not be serialized.",failure);}}private List<UUID> parseIds(String raw){try{return mapper.readValue(raw,new TypeReference<List<UUID>>(){});}catch(JacksonException failure){throw new IllegalStateException("Persisted matrix selection is invalid.",failure);}}private Map<String,JsonNode> parseMap(String raw){try{return mapper.readValue(raw,new TypeReference<LinkedHashMap<String,JsonNode>>(){});}catch(JacksonException failure){throw new IllegalStateException("Persisted matrix output is invalid.",failure);}}private Map<String,JsonNode> parseNullableMap(String raw){return raw==null?null:parseMap(raw);}private List<com.rulecraft.decisionops.runtime.DecisionExecutionService.DecisionEvaluation> parseDecisions(String raw){if(raw==null)return List.of();try{return mapper.readValue(raw,new TypeReference<List<com.rulecraft.decisionops.runtime.DecisionExecutionService.DecisionEvaluation>>(){});}catch(JacksonException failure){throw new IllegalStateException("Persisted matrix trace is invalid.",failure);}}
    private void bad(String code,String message){throw new DomainProblemException(HttpStatus.BAD_REQUEST,code,message);}private void conflict(String code,String message){throw new DomainProblemException(HttpStatus.CONFLICT,code,message);}
    public record MatrixRunCommand(UUID clientRequestId,List<UUID> testCaseIds){}
    public record MatrixRunSummary(UUID id,UUID clientRequestId,MatrixRunStatus status,int selectedCount,int passedCount,int failedCount,int errorCount,Instant startedAt,Instant completedAt){}
    public record MatrixRunView(MatrixRunSummary run,List<UUID> selectedCaseIds,List<MatrixCaseView> results){}
    public record MatrixCaseView(UUID id,int position,UUID testCaseId,long testCaseVersion,String testKey,String testName,MatrixCaseStatus status,UUID testRunId,UUID evaluationId,Long graphVersion,Map<String,JsonNode> expectedOutputs,Map<String,JsonNode> actualOutputs,List<com.rulecraft.decisionops.runtime.DecisionExecutionService.DecisionEvaluation> decisions,String errorCode,String errorDetail,Instant executedAt){}
}
